                      </div>
                    ))}
                  </div>
                </div>
                {continueCourses.length === 0 && (
                  <div className="w-full text-center py-12 text-muted-foreground">
                    <p>No has visitado ningún curso aún. ¡Explora y comienza a aprender algo nuevo!</p>
                  </div>
