// Supabase Authentication Hook - Migration from Replit Auth
import { createClient } from '@supabase/supabase-js';
import { createContext, useContext, useEffect, useState, ReactNode } from 'react';
import { useToast } from '@/hooks/use-toast';

// Initialize Supabase client for frontend
const supabaseUrl = import.meta.env.VITE_SUPABASE_URL || '';
const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY || '';

// Only create client if we have credentials
export const supabase = supabaseUrl && supabaseAnonKey 
  ? createClient(supabaseUrl, supabaseAnonKey)
  : null;

interface User {
  id: string;
  email: string;
  firstName?: string;
  lastName?: string;
  profileImageUrl?: string;
}

interface SupabaseAuthContextType {
  user: User | null;
  isLoading: boolean;
  isAuthenticated: boolean;
  supabaseUser: any | null;
  signIn: (email: string, password: string) => Promise<void>;
  signUp: (email: string, password: string, metadata?: any) => Promise<void>;
  signOut: () => Promise<void>;
  signInWithGoogle: () => Promise<void>;
  getAccessToken: () => Promise<string | null>;
}

const SupabaseAuthContext = createContext<SupabaseAuthContextType | null>(null);

export function SupabaseAuthProvider({ children }: { children: ReactNode }) {
  const { toast } = useToast();
  const [user, setUser] = useState<User | null>(null);
  const [supabaseUser, setSupabaseUser] = useState<any | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Initialize auth state
  useEffect(() => {
    if (!supabase) {
      setIsLoading(false);
      return;
    }

    // Get initial session
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (session?.user) {
        handleUserSession(session.user);
      } else {
        setIsLoading(false);
      }
    });

    // Listen for auth changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      async (event, session) => {
        if (session?.user) {
          handleUserSession(session.user);
        } else {
          setUser(null);
          setSupabaseUser(null);
          setIsLoading(false);
        }
      }
    );

    return () => subscription.unsubscribe();
  }, []);

  const handleUserSession = async (supabaseUser: any) => {
    try {
      setSupabaseUser(supabaseUser);

      // Get or create user in our database via API
      const token = (await supabase?.auth.getSession())?.data?.session?.access_token;

      if (token) {
        const response = await fetch('/api/auth/me', {
          headers: {
            'Authorization': `Bearer ${token}`,
          },
        });

        if (response.ok) {
          const userData = await response.json();
          setUser(userData);
        }
      }
    } catch (error) {
      console.error('Error handling user session:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const signIn = async (email: string, password: string) => {
    if (!supabase) {
      throw new Error('Supabase no está configurado');
    }

    setIsLoading(true);
    try {
      const { error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (error) {
        throw error;
      }

      toast({
        title: "¡Bienvenido!",
        description: "Has iniciado sesión exitosamente",
      });
    } catch (error: any) {
      toast({
        title: "Error de login",
        description: error.message || "Error al iniciar sesión",
        variant: "destructive",
      });
      throw error;
    } finally {
      setIsLoading(false);
    }
  };

  const signUp = async (email: string, password: string, metadata?: any) => {
    if (!supabase) {
      throw new Error('Supabase no está configurado');
    }

    setIsLoading(true);
    try {
      const { error } = await supabase.auth.signUp({
        email,
        password,
        options: {
          data: metadata,
        },
      });

      if (error) {
        throw error;
      }

      toast({
        title: "¡Registro exitoso!",
        description: "Verifica tu email para completar el registro",
      });
    } catch (error: any) {
      toast({
        title: "Error de registro",
        description: error.message || "Error al registrarse",
        variant: "destructive",
      });
      throw error;
    } finally {
      setIsLoading(false);
    }
  };

  const signOut = async () => {
    if (!supabase) return;

    try {
      const { error } = await supabase.auth.signOut();
      if (error) throw error;

      setUser(null);
      setSupabaseUser(null);

      toast({
        title: "Sesión cerrada",
        description: "Has cerrado sesión exitosamente",
      });
    } catch (error: any) {
      toast({
        title: "Error",
        description: error.message || "Error al cerrar sesión",
        variant: "destructive",
      });
    }
  };

  const signInWithGoogle = async () => {
    if (!supabase) {
      throw new Error('Supabase no está configurado');
    }

    try {
      const { error } = await supabase.auth.signInWithOAuth({
        provider: 'google',
        options: {
          redirectTo: `${window.location.origin}/`,
        },
      });

      if (error) throw error;
    } catch (error: any) {
      toast({
        title: "Error",
        description: error.message || "Error al iniciar sesión con Google",
        variant: "destructive",
      });
      throw error;
    }
  };

  const getAccessToken = async (): Promise<string | null> => {
    if (!supabase) return null;

    const { data: { session } } = await supabase.auth.getSession();
    return session?.access_token || null;
  };

  return (
    <SupabaseAuthContext.Provider
      value={{
        user,
        supabaseUser,
        isLoading,
        isAuthenticated: !!user,
        signIn,
        signUp,
        signOut,
        signInWithGoogle,
        getAccessToken,
      }}
    >
      {children}
    </SupabaseAuthContext.Provider>
  );
}

export function useSupabaseAuth() {
  const context = useContext(SupabaseAuthContext);
  if (!context) {
    throw new Error('useSupabaseAuth must be used within a SupabaseAuthProvider');
  }
  return context;
}

client/src/pages/room.tsx.content:
import { useParams, Link } from "wouter";
import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { Lock, Play, BookOpen, Video, Calendar, Clock, Menu, ChevronLeft } from "lucide-react";
import { cn } from "@/lib/utils";
import CourseCard from "@/components/course-card";
import Sidebar from "@/components/layout/sidebar";
import MobileNav from "@/components/layout/mobile-nav";
import MobileHeader from "@/components/layout/mobile-header";
import { PromoBanner } from "@/components/PromoBanner";
import { format } from "date-fns";
import { es } from "date-fns/locale";
import { useState } from "react";

interface Phase {
  id: string;
  title: string;
  description: string | null;
  order: number;
  releaseDate: string;
  isLocked: boolean;
  content: PhaseContent[];
}

interface PhaseContent {
  id: string;
  contentType: string;
  contentId: string;
  order: number;
  courseData?: any;
}

interface Room {
  id: string;
  title: string;
  slug: string;
  description: string | null;
  shortDescription: string | null;
  coverImageUrl: string | null;
  heroImageUrl: string | null;
  order: number;
  isPublished: boolean;
  price: number | null;
  currency: string;
  metadata: any;
}

interface PromoBannerData {
  id: string;
  roomId: string;
  title: string;
  subtitle: string | null;
  description: string | null;
  backgroundImageUrl: string | null;
  backgroundColor: string;
  ctaText: string | null;
  ctaLink: string | null;
  displayAfterPhaseOrder: number;
  order: number;
  isActive: boolean;
}

interface RoomDetailResponse {
  room: Room;
  phases: Phase[];
  promoBanners: PromoBannerData[];
  userHasAccess: boolean;
}

export default function Room() {
  const { slug } = useParams();
  const { user, isAuthenticated } = useAuth();
  const [sidebarOpen, setSidebarOpen] = useState(true);

  const { data: roomDetail, isLoading } = useQuery<RoomDetailResponse>({
    queryKey: [`/api/rooms/${slug}`],
  });

  // Get user progress for all courses in this room
  const { data: userProgress } = useQuery<Record<string, any>>({
    queryKey: [`/api/rooms/${slug}/user-progress`],
    enabled: isAuthenticated && !!slug,
  });

  if (isLoading) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="text-foreground">Cargando sala...</div>
      </div>
    );
  }

  if (!roomDetail) {
    return (
      <div className="min-h-screen bg-background flex items-center justify-center">
        <div className="text-center">
          <h1 className="text-2xl font-bold mb-4">Sala no encontrada</h1>
          <Link href="/">
            <Button>Volver al inicio</Button>
          </Link>
        </div>
      </div>
    );
  }

  const { room, phases, promoBanners, userHasAccess } = roomDetail;
  const hasAccess = userHasAccess;

  return (
    <div className="min-h-screen bg-background text-foreground">
      {/* Mobile Header */}
      <MobileHeader />

      <div className="flex relative">
        {/* Sidebar with toggle functionality */}
        {sidebarOpen && (
          <Sidebar onToggle={() => setSidebarOpen(false)} />
        )}

        {/* Reopen Button - Only visible when sidebar is closed */}
        {!sidebarOpen && (
          <button
            onClick={() => setSidebarOpen(true)}
            className="hidden lg:flex fixed top-4 left-4 z-50 items-center justify-center w-10 h-10 bg-card hover:bg-muted text-muted-foreground hover:text-foreground rounded-lg shadow-lg transition-all"
            title="Mostrar sidebar"
            data-testid="sidebar-reopen-button"
          >
            <Menu className="h-5 w-5" />
          </button>
        )}

        {/* Main Content */}
        <main className={cn(
          "flex-1 overflow-auto pb-20 lg:pb-0 transition-all duration-300",
          "md:ml-16",
          sidebarOpen ? "lg:ml-[250px]" : "lg:ml-0"
        )}>
          {/* Hero Banner - Full width image only */}
          {room.heroImageUrl && (
            <div className="relative w-full h-[clamp(300px,60vh,600px)] overflow-hidden">
              <img 
                src={room.heroImageUrl}
                alt={room.title}
                className="w-full h-full object-cover"
              />
              {/* Bottom fade to blend with content */}
              <div className="absolute bottom-0 left-0 right-0 h-32 bg-gradient-to-t from-background to-transparent" />
            </div>
          )}

          {/* Phases Section */}
          <div className="container mx-auto px-4 pb-16 -mt-32 relative z-10">
            <div className="space-y-12">
              {phases.map((phase, index) => {
                // Compute whether this phase is locked for the current user
                // Phase is locked if: user doesn't have room access OR phase release date hasn't passed
                const isLockedForUser = !hasAccess || phase.isLocked;

                // Find promo banners that should display after this phase
                const bannersAfterPhase = (promoBanners || []).filter(
                  banner => banner.displayAfterPhaseOrder === phase.order
                );

                return (
                  <div key={`phase-${phase.id}`}>
                    <div className="space-y-4">
                      {/* Phase Header */}
                      <div className="flex items-center gap-4">
                        <div className="flex-1">
                          <div className="flex items-center gap-3">
                            <h3 className="text-2xl font-bold">{phase.title}</h3>

                            {/* Show "Bloqueado" if user doesn't have room access */}
                            {!hasAccess && (
                              <Badge variant="secondary" className="gap-1">
                                <Lock className="h-3 w-3" />
                                Requiere acceso
                              </Badge>
                            )}

                            {/* Show release date for locked phases (due to future release) */}
                            {hasAccess && phase.isLocked && (
                              <Badge variant="outline" className="gap-1">
                                <Calendar className="h-3 w-3" />
                                Se desbloquea {new Date(phase.releaseDate).toLocaleDateString()}
                              </Badge>
                            )}
                          </div>

                          {phase.description && (
                            <p className="text-muted-foreground mt-1">{phase.description}</p>
                          )}
                        </div>
                      </div>

                      {/* Phase Content - Netflix Style Grid */}
                      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 xl:grid-cols-6 gap-4">
                        {phase.content.map((content) => {
                          const getHref = () => {
                            if (isLockedForUser) return "#";
                            if (content.contentType === 'course') return `/sala/${slug}/curso/${content.contentId}`;
                            if (content.contentType === 'workshop') return `/taller/${content.contentId}`;
                            if (content.contentType === 'guide') return `/guia/${content.contentId}`;
                            return "#";
                          };

                          const getBadgeText = () => {
                            if (content.contentType === 'workshop') return 'Workshop';
                            if (content.contentType === 'guide') return 'Guía';
                            return 'Curso';
                          };

                          const courseProgress = content.contentType === 'course' && userProgress?.[content.contentId];

                          const CardContent = (
                            <div className={cn(
                              "relative transition-all duration-300",
                              isLockedForUser ? "cursor-not-allowed" : "cursor-pointer hover:scale-105 hover:z-10 hover:shadow-2xl"
                            )}>
                              {/* Poster Image */}
                              <div className={cn(
                                "relative aspect-[2/3] rounded-lg overflow-hidden group-hover:rounded-b-none",
                                isLockedForUser && "opacity-50"
                              )}>
                                {content.courseData?.coverImageUrl ? (
                                  <img 
                                    src={content.courseData.coverImageUrl} 
                                    alt={content.courseData.title}
                                    className="w-full h-full object-cover"
                                  />
                                ) : (
                                  <div className="w-full h-full bg-gradient-to-br from-primary/20 to-primary/5 flex items-center justify-center">
                                    {content.contentType === 'workshop' && (
                                      <Video className="h-16 w-16 text-primary/40" />
                                    )}
                                    {content.contentType === 'guide' && (
                                      <BookOpen className="h-16 w-16 text-primary/40" />
                                    )}
                                    {content.contentType === 'course' && (
                                      <Play className="h-16 w-16 text-primary/40" />
                                    )}
                                  </div>
                                )}

                                {/* Lock Overlay */}
                                {isLockedForUser && (
                                  <div className="absolute inset-0 bg-black/60 flex items-center justify-center">
                                    <Lock className="h-12 w-12 text-white" />
                                  </div>
                                )}
                              </div>

                              {/* Title and Badge - Show below on hover */}
                              <div className="max-h-0 group-hover:max-h-40 overflow-hidden transition-all duration-300 bg-black rounded-b-lg">
                                <div className="p-3 space-y-1">
                                  <h4 className="text-white font-semibold text-sm line-clamp-2 leading-tight">
                                    {content.courseData?.title || 'Sin título'}
                                  </h4>

                                  {/* Progress info shown on hover */}
                                  {courseProgress && (
                                    <>
                                      {courseProgress.lastLessonTitle && (
                                        <p className="text-white/70 text-xs line-clamp-1">
                                          {courseProgress.lastLessonTitle}
                                        </p>
                                      )}
                                      {courseProgress.subscriptionExpiresAt && (
                                        <p className="text-white/60 text-xs flex items-center gap-1">
                                          <Clock className="h-3 w-3" />
                                          Acceso hasta {format(new Date(courseProgress.subscriptionExpiresAt), "dd/MM/yy", { locale: es })}
                                        </p>
                                      )}
                                      {/* Progress bar */}
                                      <div className="mt-2 space-y-1">
                                        <div className="h-1 bg-white/20 rounded-full overflow-hidden">
                                          <div 
                                            className="h-full bg-[#faa318] transition-all duration-300"
                                            style={{ width: `${courseProgress.progressPercentage}%` }}
                                          />
                                        </div>
                                        <p className="text-white/60 text-xs text-right">
                                          {courseProgress.progressPercentage}%
                                        </p>
                                      </div>
                                    </>
                                  )}
                                </div>
                              </div>
                            </div>
                          );

                          return (
                            <div key={content.id} className="group">
                              <Link href={getHref()}>
                                {CardContent}
                              </Link>
                            </div>
                          );
                        })}

                        {phase.content.length === 0 && (
                          <div className="col-span-full p-12 text-center text-muted-foreground">
                            <p>No hay contenido disponible en esta fase todavía</p>
                          </div>
                        )}
                      </div>
                    </div>

                    {/* Promo Banners After Phase */}
                    {bannersAfterPhase.map(banner => (
                      <div key={banner.id} className="my-12">
                        <PromoBanner
                          title={banner.title}
                          subtitle={banner.subtitle || undefined}
                          description={banner.description || undefined}
                          ctaText={banner.ctaText || undefined}
                          ctaLink={banner.ctaLink || undefined}
                          backgroundImage={banner.backgroundImageUrl || undefined}
                          backgroundColor={banner.backgroundColor}
                        />
                      </div>
                    ))}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Features Section */}
          {room.metadata?.features && room.metadata.features.length > 0 && (
            <div className="bg-muted/50 py-16">
              <div className="container mx-auto px-4">
                <h2 className="text-2xl font-bold mb-8">Lo que aprenderás</h2>
                <div className="grid md:grid-cols-3 gap-6">
                  {room.metadata.features.map((feature: string, index: number) => (
                    <div key={index} className="flex items-start gap-3">
                      <div className="p-2 rounded-full bg-primary/10">
                        <Play className="h-5 w-5 text-primary" />
                      </div>
                      <p className="text-lg">{feature}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}
        </main>
      </div>

      {/* Mobile Navigation */}
      <MobileNav />
    </div>
  );
}

