    onSuccess: () => {
      toast({
        title: "Recurso guardado",
        description: "El recurso se ha guardado exitosamente"
      });
      queryClient.invalidateQueries({ queryKey: ["/api/resources", workshopId] });
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "No se pudo guardar el recurso",
        variant: "destructive"
      });
    }
  });

