                            {hasSubLessons && (
                              <button
                                onClick={(e) => {
                                  e.stopPropagation();
                                  toggleModuleCollapse(module.id);
                                }}
                                className="p-1 hover:bg-muted/30 rounded transition-colors"
                              >
                                <ChevronRight 
                                  size={16} 
                                  className={cn(
                                    "text-muted-foreground transition-transform",
                                    !isCollapsed && "rotate-90"
                                  )}
                                />
                              </button>
                            )}
                          </div>
                        </div>
                      </div>

