                    data-testid="button-final-exam-desktop"
                    onClick={() => {
                      setIsExamModalOpen(true);
                      setCurrentQuestionIndex(0);
                      setSelectedAnswers({});
                    }}
                  >
                    🎓 Tomar el examen final
                  </button>
                </div>
              )}

