import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { useAdmin } from "@/hooks/useAdmin";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Textarea } from "@/components/ui/textarea";
import Sidebar from "@/components/layout/sidebar";
import MobileNav from "@/components/layout/mobile-nav";
import MobileHeader from "@/components/layout/mobile-header";
import { Link } from "wouter";
import { MessageCircle, CheckCircle, Filter, Reply, Eye, Trash2 } from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { es } from "date-fns/locale";

interface CommentUser {
  firstName: string;
  lastName: string;
  profileImageUrl: string | null;
}

interface Comment {
  id: string;
  content: string;
  createdAt: string;
  userId: string;
  lessonId: string;
  parentCommentId: string | null;
  isAdminReviewed: boolean;
  depth: number;
  replyCount: number;
  user: CommentUser;
  replies: Comment[];
  roomSlug?: string | null;
}

interface Lesson {
  id: string;
  title: string;
  courseId: string;
}

interface Course {
  id: string;
  title: string;
}

export default function AdminComments() {
  const { isLoading: adminLoading, isAdmin } = useAdmin();
  const [filter, setFilter] = useState<'all' | 'pending' | 'reviewed'>('pending');
  const [replyingTo, setReplyingTo] = useState<string | null>(null);
  const [replyContent, setReplyContent] = useState("");

  // Fetch all comments with filters
  const { data: commentsData = [], isLoading: commentsLoading } = useQuery<Array<Comment & {
    lesson: { id: string; title: string; courseId: string };
    course: { id: string; title: string };
  }>>({
    queryKey: ['/api/admin/comments', `?filter=${filter}`],
    enabled: isAdmin,
  });

  const { data: unreadData } = useQuery<{ count: number }>({
    queryKey: ['/api/admin/comments/unread-count'],
    enabled: isAdmin,
  });

  const unreadCount = unreadData?.count || 0;
  const reviewedCount = commentsData.filter(c => c.isAdminReviewed).length;
  const totalCount = commentsData.length;

  const markReviewedMutation = useMutation({
    mutationFn: async (commentId: string) => {
      return apiRequest('PATCH', `/api/admin/comments/${commentId}/status`, { status: 'approved' });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/comments/unread-count'], refetchType: 'active' });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/comments'], refetchType: 'active' });
    },
  });

  const deleteCommentMutation = useMutation({
    mutationFn: async (commentId: string) => {
      return apiRequest('DELETE', `/api/admin/comments/${commentId}`, {});
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['/api/admin/comments/unread-count'], refetchType: 'active' });
      queryClient.invalidateQueries({ queryKey: ['/api/admin/comments'], refetchType: 'active' });
    },
  });

  if (adminLoading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-purple-600"></div>
      </div>
    );
  }

  if (!isAdmin) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen space-y-4">
        <h1 className="text-2xl font-bold text-red-500">Acceso Denegado</h1>
        <p className="text-gray-400">No tienes privilegios de administrador.</p>
        <Link href="/">
          <Button>Volver al Inicio</Button>
        </Link>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-dark-bg text-white">
      <MobileHeader />

      <div className="flex">
        <div className="hidden lg:block">
          <Sidebar />
        </div>

        <main className="flex-1 overflow-auto pb-20 lg:pb-0 lg:ml-[250px]">
          <div className="container mx-auto px-4 py-8">
            <div className="flex justify-between items-center mb-8">
              <div>
                <h1 className="text-3xl font-bold text-white flex items-center gap-3">
                  <MessageCircle className="h-8 w-8" />
                  Gestión de Comentarios
                </h1>
                <p className="text-gray-400 mt-2">
                  Revisa y modera los comentarios de los estudiantes
                </p>
              </div>
              <Link href="/admin">
                <Button variant="outline">Volver al Panel</Button>
              </Link>
            </div>

            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
              <Card className="bg-slate-900/50 border-slate-700">
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium text-white">
                    Sin Revisar
                  </CardTitle>
                  <MessageCircle className="h-4 w-4 text-amber-400" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold text-white">{unreadCount}</div>
                  <p className="text-xs text-gray-400">
                    Comentarios pendientes de revisión
                  </p>
                </CardContent>
              </Card>

              <Card className="bg-slate-900/50 border-slate-700">
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium text-white">
                    Revisados
                  </CardTitle>
                  <CheckCircle className="h-4 w-4 text-green-400" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold text-white">{reviewedCount}</div>
                  <p className="text-xs text-gray-400">
                    Comentarios revisados
                  </p>
                </CardContent>
              </Card>

              <Card className="bg-slate-900/50 border-slate-700">
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-sm font-medium text-white">
                    Total
                  </CardTitle>
                  <MessageCircle className="h-4 w-4 text-purple-400" />
                </CardHeader>
                <CardContent>
                  <div className="text-2xl font-bold text-white">{totalCount}</div>
                  <p className="text-xs text-gray-400">
                    Todos los comentarios
                  </p>
                </CardContent>
              </Card>
            </div>

            {/* Filters */}
            <div className="mb-6 flex gap-2">
              <Button
                variant={filter === 'all' ? 'default' : 'outline'}
                onClick={() => setFilter('all')}
                size="sm"
              >
                <Filter className="h-4 w-4 mr-2" />
                Todos
              </Button>
              <Button
                variant={filter === 'pending' ? 'default' : 'outline'}
                onClick={() => setFilter('pending')}
                size="sm"
              >
                <MessageCircle className="h-4 w-4 mr-2" />
                Pendientes
              </Button>
              <Button
                variant={filter === 'reviewed' ? 'default' : 'outline'}
                onClick={() => setFilter('reviewed')}
                size="sm"
              >
                <CheckCircle className="h-4 w-4 mr-2" />
                Revisados
              </Button>
            </div>

            {/* Comments list */}
            {commentsLoading ? (
              <div className="space-y-4">
                {[1, 2, 3].map((i) => (
                  <Card key={i} className="bg-slate-900/50 border-slate-700 animate-pulse">
                    <CardContent className="pt-6">
                      <div className="flex gap-3">
                        <div className="h-10 w-10 rounded-full bg-slate-700" />
                        <div className="flex-1 space-y-2">
                          <div className="h-4 w-32 bg-slate-700 rounded" />
                          <div className="h-16 bg-slate-700 rounded" />
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            ) : commentsData.length === 0 ? (
              <Card className="bg-slate-900/50 border-slate-700">
                <CardContent className="pt-6">
                  <div className="text-center py-12 text-gray-400">
                    <MessageCircle className="h-16 w-16 mx-auto mb-4 opacity-50" />
                    <p className="text-lg font-medium mb-2">
                      No hay comentarios {filter === 'pending' ? 'pendientes' : filter === 'reviewed' ? 'revisados' : ''}
                    </p>
                    <p className="text-sm">
                      {filter === 'pending' 
                        ? 'Todos los comentarios han sido revisados' 
                        : 'Los comentarios aparecerán aquí cuando los estudiantes participen'}
                    </p>
                  </div>
                </CardContent>
              </Card>
            ) : (
              <div className="space-y-4">
                {commentsData.map((comment) => {
                  const initials = `${comment.user.firstName[0]}${comment.user.lastName[0]}`.toUpperCase();
                  const isReplying = replyingTo === comment.id;

                  return (
                    <Card 
                      key={comment.id} 
                      className="bg-slate-900/50 border-slate-700 hover:bg-slate-900/70 transition-colors"
                      data-testid={`admin-comment-${comment.id}`}
                    >
                      <CardContent className="pt-6">
                        <div className="flex gap-3">
                          <Avatar className="h-10 w-10">
                            <AvatarImage src={comment.user.profileImageUrl || undefined} />
                            <AvatarFallback>{initials}</AvatarFallback>
                          </Avatar>

                          <div className="flex-1">
                            <div className="flex items-start justify-between mb-2">
                              <div>
                                <div className="flex items-baseline gap-2 mb-1">
                                  <span className="font-medium text-white">
                                    {comment.user.firstName} {comment.user.lastName}
                                  </span>
                                  <span className="text-xs text-gray-400">
                                    {formatDistanceToNow(new Date(comment.createdAt), { addSuffix: true, locale: es })}
                                  </span>
                                </div>
                                <div className="flex items-center gap-2 text-sm text-gray-400">
                                  <Link href={`/course/${comment.lesson.courseId}/lesson/${comment.lesson.id}`}>
                                    <span className="hover:text-purple-400 transition-colors">
                                      {comment.course.title} • {comment.lesson.title}
                                    </span>
                                  </Link>
                                </div>
                              </div>

                              <Badge 
                                variant={comment.isAdminReviewed ? "default" : "secondary"}
                                className={comment.isAdminReviewed ? "bg-green-600" : "bg-amber-600"}
                              >
                                {comment.isAdminReviewed ? (
                                  <><CheckCircle className="h-3 w-3 mr-1" /> Revisado</>
                                ) : (
                                  <><Eye className="h-3 w-3 mr-1" /> Pendiente</>
                                )}
                              </Badge>
                            </div>

                            <p className="text-sm text-white mb-3 whitespace-pre-wrap">
                              {comment.content}
                            </p>

                            <div className="flex gap-2">
                              {!comment.isAdminReviewed && (
                                <Button
                                  size="sm"
                                  variant="outline"
                                  onClick={() => markReviewedMutation.mutate(comment.id)}
                                  disabled={markReviewedMutation.isPending}
                                  data-testid={`button-approve-${comment.id}`}
                                >
                                  <CheckCircle className="h-3 w-3 mr-1" />
                                  Aprobar
                                </Button>
                              )}
                              {comment.roomSlug ? (
                                <Link href={`/sala/${comment.roomSlug}/curso/${comment.lesson.courseId}`}>
                                  <Button size="sm" variant="ghost">
                                    <MessageCircle className="h-3 w-3 mr-1" />
                                    Ver en contexto
                                  </Button>
                                </Link>
                              ) : (
                                <Link href={`/course/${comment.lesson.courseId}/lesson/${comment.lesson.id}#comments`}>
                                  <Button size="sm" variant="ghost">
                                    <MessageCircle className="h-3 w-3 mr-1" />
                                    Ver en contexto
                                  </Button>
                                </Link>
                              )}
                              <Button
                                size="sm"
                                variant="ghost"
                                onClick={() => {
                                  if (confirm('¿Estás seguro de que quieres eliminar este comentario? Esta acción no se puede deshacer.')) {
                                    deleteCommentMutation.mutate(comment.id);
                                  }
                                }}
                                disabled={deleteCommentMutation.isPending}
                                data-testid={`button-delete-${comment.id}`}
                                className="text-red-400 hover:text-red-300 hover:bg-red-950"
                              >
                                <Trash2 className="h-3 w-3 mr-1" />
                                Eliminar
                              </Button>
                            </div>
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  );
                })}
              </div>
            )}
          </div>
        </main>
      </div>

      <MobileNav />
    </div>
  );
}

client/src/components/LessonComments.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Card, CardContent } from "@/components/ui/card";
import { MessageCircle, Send, Reply, Heart } from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { es } from "date-fns/locale";

interface Comment {
  id: string;
  content: string;
  createdAt: string;
  userId: string;
  lessonId: string;
  parentCommentId: string | null;
  isAdminReviewed: boolean;
  depth: number;
  replyCount: number;
  likeCount: number;
  isLikedByCurrentUser?: boolean;
  user: {
    firstName: string;
    lastName: string;
    profileImageUrl: string | null;
  };
  replies: Comment[];
}

interface LessonCommentsProps {
  lessonId: string;
}

interface CommentItemProps {
  comment: Comment;
  depth?: number;
  replyTo: string | null;
  setReplyTo: (id: string | null) => void;
  replyContents: Record<string, string>;
  setReplyContent: (commentId: string, content: string) => void;
  getReplyContent: (commentId: string) => string;
  handleSubmitReply: (parentId: string) => void;
  toggleLikeMutation: any;
  createReplyMutation: any;
  setReplyContents: React.Dispatch<React.SetStateAction<Record<string, string>>>;
}

const CommentItem = ({ 
  comment, 
  depth = 0, 
  replyTo, 
  setReplyTo,
  replyContents,
  getReplyContent, 
  setReplyContent, 
  handleSubmitReply, 
  toggleLikeMutation, 
  createReplyMutation,
  setReplyContents
}: CommentItemProps) => {
  const initials = `${comment.user.firstName[0]}${comment.user.lastName[0]}`.toUpperCase();
  const isReplying = replyTo === comment.id;

  return (
    <div 
      className={`${depth > 0 ? 'ml-8 mt-4 border-l-2 border-border pl-4' : 'mb-6'}`}
      data-testid={`comment-${comment.id}`}
    >
      <div className="flex gap-3">
        <Avatar className="h-8 w-8">
          <AvatarImage src={comment.user.profileImageUrl || undefined} />
          <AvatarFallback className="text-xs">{initials}</AvatarFallback>
        </Avatar>

        <div className="flex-1">
          <div className="flex items-baseline gap-2 mb-1">
            <span className="font-medium text-sm" data-testid={`comment-author-${comment.id}`}>
              {comment.user.firstName} {comment.user.lastName}
            </span>
            <span className="text-xs text-muted-foreground" data-testid={`comment-time-${comment.id}`}>
              {formatDistanceToNow(new Date(comment.createdAt), { addSuffix: true, locale: es })}
            </span>
          </div>

          <p className="text-sm mb-2 whitespace-pre-wrap" data-testid={`comment-content-${comment.id}`}>
            {comment.content}
          </p>

          <div className="flex items-center gap-2">
            <Button
              variant="ghost"
              size="sm"
              className={`h-7 px-2 text-xs ${comment.isLikedByCurrentUser ? 'text-red-500' : ''}`}
              onClick={() => toggleLikeMutation.mutate(comment.id)}
              disabled={toggleLikeMutation.isPending}
              data-testid={`button-like-${comment.id}`}
            >
              <Heart 
                className={`h-3 w-3 mr-1 ${comment.isLikedByCurrentUser ? 'fill-current' : ''}`}
              />
              {comment.likeCount > 0 && <span>{comment.likeCount}</span>}
            </Button>

            <Button
              variant="ghost"
              size="sm"
              className="h-7 px-2 text-xs"
              onClick={() => setReplyTo(isReplying ? null : comment.id)}
              data-testid={`button-reply-${comment.id}`}
            >
              <Reply className="h-3 w-3 mr-1" />
              Responder
            </Button>
          </div>

          {isReplying && (
            <div className="mt-3 space-y-2" data-testid={`reply-form-${comment.id}`}>
              <Textarea
                placeholder="Escribe tu respuesta..."
                value={getReplyContent(comment.id)}
                onChange={(e) => setReplyContent(comment.id, e.target.value)}
                className="min-h-[80px] text-sm"
                data-testid={`textarea-reply-${comment.id}`}
              />
              <div className="flex gap-2">
                <Button
                  size="sm"
                  onClick={() => handleSubmitReply(comment.id)}
                  disabled={createReplyMutation.isPending || !getReplyContent(comment.id).trim()}
                  data-testid={`button-submit-reply-${comment.id}`}
                >
                  <Send className="h-3 w-3 mr-1" />
                  {createReplyMutation.isPending ? 'Enviando...' : 'Enviar'}
                </Button>
                <Button
                  size="sm"
                  variant="ghost"
                  onClick={() => {
                    setReplyTo(null);
                    setReplyContents(prev => {
                      const newContents = { ...prev };
                      delete newContents[comment.id];
                      return newContents;
                    });
                  }}
                  data-testid={`button-cancel-reply-${comment.id}`}
                >
                  Cancelar
                </Button>
              </div>
            </div>
          )}

          {comment.replies && comment.replies.length > 0 && (
            <div className="mt-4">
              {comment.replies.map((reply) => (
                <CommentItem 
                  key={reply.id} 
                  comment={reply} 
                  depth={depth + 1}
                  replyTo={replyTo}
                  setReplyTo={setReplyTo}
                  replyContents={replyContents}
                  getReplyContent={getReplyContent}
                  setReplyContent={setReplyContent}
                  handleSubmitReply={handleSubmitReply}
                  toggleLikeMutation={toggleLikeMutation}
                  createReplyMutation={createReplyMutation}
                  setReplyContents={setReplyContents}
                />
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export function LessonComments({ lessonId }: LessonCommentsProps) {
  const [newComment, setNewComment] = useState("");
  const [replyTo, setReplyTo] = useState<string | null>(null);
  const [replyContents, setReplyContents] = useState<Record<string, string>>({});

  const { data: comments = [], isLoading, refetch } = useQuery<Comment[]>({
    queryKey: ['/api/lessons', lessonId, 'comments'],
  });

  const createCommentMutation = useMutation({
    mutationFn: async (content: string) => {
      return apiRequest('POST', `/api/lessons/${lessonId}/comments`, { content, lessonId });
    },
    onSuccess: async () => {
      setNewComment("");
      // Force refetch instead of invalidation
      await refetch();
    },
  });

  const createReplyMutation = useMutation({
    mutationFn: async ({ parentId, content }: { parentId: string; content: string }) => {
      return apiRequest('POST', `/api/comments/${parentId}/replies`, { content, lessonId });
    },
    onSuccess: async (_, variables) => {
      setReplyTo(null);
      setReplyContents(prev => {
        const newContents = { ...prev };
        delete newContents[variables.parentId];
        return newContents;
      });
      // Force refetch instead of invalidation
      await refetch();
    },
  });

  const toggleLikeMutation = useMutation({
    mutationFn: async (commentId: string) => {
      return apiRequest('POST', `/api/comments/${commentId}/like`, {});
    },
    onSuccess: async () => {
      // Force refetch to update like counts and state
      await refetch();
    },
  });

  const handleSubmitComment = () => {
    if (newComment.trim()) {
      createCommentMutation.mutate(newComment);
    }
  };

  const handleSubmitReply = (parentId: string) => {
    const content = replyContents[parentId] || "";
    if (content.trim()) {
      createReplyMutation.mutate({ parentId, content });
    }
  };

  const setReplyContent = (commentId: string, content: string) => {
    setReplyContents(prev => ({ ...prev, [commentId]: content }));
  };

  const getReplyContent = (commentId: string) => {
    return replyContents[commentId] || "";
  };

  return (
    <div className="mt-12 pt-8 border-t border-border" id="comments">
      <div className="flex items-center gap-2 mb-6">
        <MessageCircle className="h-5 w-5" />
        <h2 className="text-xl font-semibold">
          Comentarios ({comments.length})
        </h2>
      </div>

      <Card className="mb-6">
        <CardContent className="pt-6">
          <Textarea
            placeholder="Comparte tus dudas, ideas o experiencias sobre esta lección..."
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
            className="min-h-[120px] mb-3"
            data-testid="textarea-new-comment"
          />
          <Button
            onClick={handleSubmitComment}
            disabled={createCommentMutation.isPending || !newComment.trim()}
            data-testid="button-submit-comment"
            className="bg-[#faa318] text-white hover:bg-[#faa318]/90"
          >
            <Send className="h-4 w-4 mr-2" />
            {createCommentMutation.isPending ? 'Publicando...' : 'Publicar comentario'}
          </Button>
        </CardContent>
      </Card>

      {isLoading ? (
        <div className="space-y-4">
          {[1, 2, 3].map((i) => (
            <div key={i} className="flex gap-3 animate-pulse">
              <div className="h-8 w-8 rounded-full bg-muted" />
              <div className="flex-1 space-y-2">
                <div className="h-4 w-32 bg-muted rounded" />
                <div className="h-12 bg-muted rounded" />
              </div>
            </div>
          ))}
        </div>
      ) : comments.length === 0 ? (
        <div className="text-center py-12 text-muted-foreground">
          <MessageCircle className="h-12 w-12 mx-auto mb-3 opacity-50" />
          <p>Sé el primero en comentar esta lección</p>
        </div>
      ) : (
        <div className="space-y-4">
          {comments.map((comment) => (
            <CommentItem 
              key={comment.id} 
              comment={comment}
              replyTo={replyTo}
              setReplyTo={setReplyTo}
              replyContents={replyContents}
              setReplyContent={setReplyContent}
              getReplyContent={getReplyContent}
              handleSubmitReply={handleSubmitReply}
              toggleLikeMutation={toggleLikeMutation}
              createReplyMutation={createReplyMutation}
              setReplyContents={setReplyContents}
            />
          ))}
        </div>
      )}
    </div>
  );
}

